#!/usr/bin/env python3
"""Opt-in finite qualification; expected facts are never generated by the reader."""
import argparse,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from experiments import source_links,url_resolution
from scripts.source_http_check import fixture

def check(node,output):
    output.mkdir(parents=True,exist_ok=False);rows=[]
    cases=fixture('url-resolution-v1.json')['cases']
    results=url_resolution.resolve([c['request'] for c in cases],node=node)
    (output/'url-results.json').write_text(json.dumps(results,ensure_ascii=False,indent=2)+'\n')
    for c,r in zip(cases,results['results']):
        rows.append({'group':'url','id':c['id'],'expected':c['expected_href'],'actual':r.get('href'),
            'matches':r.get('href')==c['expected_href'] and r['ok']==(c['expected_href'] is not None)})
    for c in fixture('source-links-v1.json')['cases']:
        r=source_links.inventory(c['html'].encode(),content_types=['text/html; charset=utf-8'],
            document_url=c['document_url'],csp_headers=[],node=node)
        (output/(c['id']+'.json')).write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
        for mode,reading in r['readings'].items():
            actual=source_links.project(reading)
            rows.append({'group':'source','id':c['id'],'mode':mode,'expected':c['expected'][mode],
                'actual':actual,'matches':actual==c['expected'][mode]})
    return {'kind':'source-link-qualification','synthetic':True,'normative_effect':'none',
        'matched':sum(r['matches'] for r in rows),'total':len(rows),'rows':rows,'source_sha256':source_links.identity(),
        'qualification_script_sha256':source_links.sha(Path(__file__).read_bytes()),
        'scope':'50 authored URL cases and 22 authored static documents under two alternatives. No browser, CSP execution, TSEP decision or whole-standard conformance claim.'}

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--node',required=True);p.add_argument('--output-dir',type=Path,required=True)
    a=p.parse_args();r=check(a.node,a.output_dir)
    (a.output_dir/'qualification.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({k:v for k,v in r.items() if k not in ('rows','source_sha256')}))
    return 0 if r['matched']==r['total'] else 1
if __name__=='__main__':sys.exit(main())
